import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.Ccn6roXv.js";const u=JSON.parse('{"title":"2. TanStack Start basics","description":"What TanStack Start is, what it is for, and where server functions fit.","frontmatter":{"title":"2. TanStack Start basics","description":"What TanStack Start is, what it is for, and where server functions fit."},"headers":[],"relativePath":"guide/02-tanstack-start-basics.md","filePath":"guide/02-tanstack-start-basics.md"}'),r={name:"guide/02-tanstack-start-basics.md"};function n(o,e,l,c,p,h){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="tanstack-start-basics" tabindex="-1">TanStack Start basics <a class="header-anchor" href="#tanstack-start-basics" aria-label="Permalink to &quot;TanStack Start basics&quot;">​</a></h1><p>TanStack Start is a full-stack React framework built on TanStack Router.</p><p>It lets developers build routes, server-rendered pages, and server-side logic in one TypeScript project.</p><h2 id="what-developers-use-it-for" tabindex="-1">What developers use it for <a class="header-anchor" href="#what-developers-use-it-for" aria-label="Permalink to &quot;What developers use it for&quot;">​</a></h2><p>Developers use TanStack Start to:</p><ul><li>Build React pages and layouts</li><li>Load data for routes</li><li>Run code on the server</li><li>Share types between client code and server code</li><li>Avoid hand-writing many small API routes</li></ul><p>That last point matters for security. A server function can feel like a normal TypeScript function call, but it still crosses a network trust boundary.</p><h2 id="what-server-functions-are" tabindex="-1">What server functions are <a class="header-anchor" href="#what-server-functions-are" aria-label="Permalink to &quot;What server functions are&quot;">​</a></h2><p>A server function is a function that the browser can call, but the implementation runs on the server.</p><p>From a developer perspective, this is convenient:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> updateProfile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ data: formValues })</span></span></code></pre></div><p>From a security perspective, this is still an HTTP request.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Browser -&gt; server function endpoint -&gt; validator -&gt; handler</span></span></code></pre></div><h2 id="why-this-abstraction-is-useful" tabindex="-1">Why this abstraction is useful <a class="header-anchor" href="#why-this-abstraction-is-useful" aria-label="Permalink to &quot;Why this abstraction is useful&quot;">​</a></h2><p>Server functions reduce boilerplate.</p><p>They can also make it less obvious where validation, authorization, and serialization happen.</p><p>Good security work is not about distrusting the framework. It is about locating the exact boundary where untrusted data becomes server-side data.</p><h2 id="security-property" tabindex="-1">Security property <a class="header-anchor" href="#security-property" aria-label="Permalink to &quot;Security property&quot;">​</a></h2><p>The property to preserve is explicit server authority:</p><ul><li>The browser may request an action.</li><li>The server decides whether the action is allowed.</li><li>Shared TypeScript types do not replace runtime checks.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p>Next, look at how a developer writes a server function.</p>',22)])])}const k=t(r,[["render",n]]);export{u as __pageData,k as default};
